examples.css:
body { font-family: Georgia, serif; width: 420px; background: hsl(0 0% 94%); padding: 16px; }
h1 { font-size: 40px; text-transform: capitalize; text-decoration: underline double #61677a; text-decoration-thickness: 2px; text-shadow: -2px -2px 5px rgba(255,0,0,.25); letter-spacing: 2px; }
.lead { line-height: 1.7; letter-spacing: 0.5px; word-spacing: 2px; text-align: justify; }
a { color: crimson; text-decoration: none; }
a:hover { text-decoration: underline wavy; text-underline-offset: 4px; }

body { font-family: sans-serif; width: 420px; }
.grad { font-size: 36px; background: linear-gradient(90deg,#f06,#48f); -webkit-background-clip: text; background-clip: text; color: transparent; }
.drop::first-letter { font-size: 56px; float: left; line-height: 0.9; padding-right: 8px; color: #ae445a; font-weight: bold; }

p { font-family: system-ui, "Segoe UI", Arial, sans-serif; font-size: 1.1rem; margin: 6px 0; }
.w1 { font-weight: 300; } .w4 { font-weight: 400; } .w7 { font-weight: 700; }
.it { font-style: italic; }
.sc { font-variant: small-caps; }
.mono { font-family: "Courier New", monospace; }

.hero { height: 180px; display: grid; place-items: center; text-align: center; color: #fff; font-family: sans-serif;
  background:
    linear-gradient(to right top, rgba(5,25,55,.8), rgba(0,191,114,.6)),
    repeating-linear-gradient(45deg, #334 0 10px, #556 10px 20px);
  background-size: cover; border-radius: 10px; }

.tile { width: 300px; height: 150px; border: 2px solid #333;
  background-color: #fef3c7;
  background-image: radial-gradient(circle, #f59e0b 6px, transparent 7px);
  background-size: 30px 30px;
  background-repeat: repeat;
  background-position: 5px 5px; }

body { display: flex; gap: 12px; }
.g { width: 120px; height: 120px; border-radius: 12px; }
.lin { background: linear-gradient(to right top, #051937, #004d7a, #008793, #00bf72, #a8eb12); }
.rad { background: radial-gradient(circle at center, #ff5733 0%, #ffc300 25%, #2980b9 60%, #33ff57 100%); }
.con { background: conic-gradient(red, yellow, lime, aqua, blue, magenta, red); border-radius: 50%; }

.link { display: inline-block; background: #fff; padding: 10px 32px; border-radius: 5px; font: bold 22px sans-serif; text-decoration: none; border: 2px solid #080a0c; }
.link:link { color: #080a0c; }
.link:visited { color: #d67e03; }
.link:hover { color: #0062ff; border-color: #0062ff; }
.link:active { color: #f31559; }

body { font-family: sans-serif; }
.steps { list-style: none; counter-reset: step; padding: 0; }
.steps li { counter-increment: step; margin: 6px 0; }
.steps li::before { content: counter(step); display: inline-grid; place-items: center; width: 24px; height: 24px; margin-right: 8px; border-radius: 50%; background: #2965f1; color: #fff; font-size: 13px; }
.check { padding-left: 20px; }
.check li::marker { content: "\2714  "; color: seagreen; }

.row { display: flex; gap: 12px; font-family: sans-serif; font-size: 13px; text-align: center; }
figure { margin: 0; }
img { width: 100px; height: 100px; background: #ddd; border: 1px solid #999; display: block; }
.a { object-fit: fill; }
.b { object-fit: contain; }
.c { object-fit: cover; }

body { font-family: sans-serif; display: flex; gap: 12px; align-items: flex-start; }
.card { background: linear-gradient(135deg,#6a11cb,#2575fc); color: #fff; display: grid; place-items: center; border-radius: 10px; }
.video { width: 220px; aspect-ratio: 16 / 9; }
.square { width: 120px; aspect-ratio: 1; }
